actions.script:
const params = ec.web.parameters
const found = sri.getShellSearch(params.text, params.groups, params.limit)
if (found != null) ec.web.sendJsonResponse(found)

const params = ec.web.parameters
const values = params.values == null || params.values === '' ? [] : String(params.values).split(',').map((value) => value.trim()).filter((value) => value)
const out = ec.service.sync().name('org.moqui.impl.StatusServices.get#ListViewColumns').parameters({values: values.slice(0, 500),
    statusTypeId: params.statusTypeId || null, statusFlowId: params.statusFlowId || null,
    status: String(params.status || '') === 'true'}).disableAuthz().call() || {}
const columns = Array.from(out.columns || []).map((column) => ({value: column.value, label: column.label, color: column.color ?? null}))
const transitions = {}
for (const step of Array.from(out.flow || [])) (transitions[step.statusId] = transitions[step.statusId] || []).push(step.toStatusId)
const colors = {}
for (const column of columns) if (column.color) colors[column.value] = column.color
ec.web.sendJsonResponse({columns: columns, transitions: transitions, colors: colors})

const params = ec.web.parameters
const list = (value) => value == null || value === '' ? null : String(value).split(',').map((id) => id.trim()).filter((id) => id)
const readOnly = String(params.readOnly || '') === 'true'
const allowed = readOnly ? [] : (params.allowedStatusIds == null ? null : (list(params.allowedStatusIds) || []))
const out = ec.service.sync().name('org.moqui.impl.StatusServices.get#StatusBar').parameters({statusId: params.statusId || null,
    statusTypeId: params.statusTypeId || null, statusFlowId: params.statusFlowId || null, stageStatusIds: list(params.stages),
    allowedToStatusIds: allowed}).disableAuthz().call() || {}
ec.web.sendJsonResponse({current: out.current ?? null, stages: out.stages || [], transitions: out.transitions || [], next: out.next ?? null})

if (!ec.user.userId) {
    ec.web.sendJsonError(401, 'Authentication required')
} else {
    // the current user's own counts (no userId is passed): no app's authorization covers this or the counts
    // service the theme names, so it runs without authorization, as shellData does
    const out = ec.service.sync().name('org.moqui.impl.ShellServices.get#ShellCounts').disableAuthz().call()
    ec.web.sendJsonResponse({counts: out.counts ?? null})
}

if (!ec.user.userId) { ec.web.sendJsonError(401, 'Authentication required') } else {
    const out = ec.service.sync().name('org.moqui.impl.ChatServices.get#UserStatuses').parameter('userIdList', [ec.user.userId])
            .disableAuthz().call()
    ec.web.sendJsonResponse({myStatus: out ? out.myStatus ?? null : null})
}

if (!ec.user.userId) { ec.web.sendJsonError(401, 'Authentication required') } else {
    const params = ec.web.parameters
    const call = {}
    for (const name of ['status', 'statusText', 'emoji']) if (params[name] != null) call[name] = String(params[name])
    // the client sends epoch millis
    if (params.clearAtDate) call.clearAtDate = /^\d+$/.test(String(params.clearAtDate)) ? Number(params.clearAtDate) : String(params.clearAtDate)
    if (params.clearAfterMinutes != null && params.clearAfterMinutes !== '') call.clearAfterMinutes = Number(params.clearAfterMinutes)
    if (String(params.clearStatus) === 'true') call.clearStatus = true
    const out = ec.service.sync().name('org.moqui.impl.ChatServices.set#UserStatus').parameters(call).disableAuthz().call()
    ec.web.sendJsonResponse({myStatus: out ? out.myStatus ?? null : null})
}

if (!ec.user.userId) { ec.web.sendJsonError(401, 'Authentication required') } else {
    const idle = Number(ec.web.parameters.idleSeconds)
    const out = ec.service.sync().name('org.moqui.impl.ChatServices.heartbeat#UserStatus')
            .parameters(Number.isFinite(idle) ? {idleSeconds: Math.max(0, Math.floor(idle))} : {active: true}).disableAuthz().call()
    ec.web.sendJsonResponse({myStatus: out ? out.myStatus ?? null : null})
}

if (!ec.user.userId) { ec.web.sendJsonError(401, 'Authentication required') } else {
    const ids = String(ec.web.parameters.userIds || '').split(',').map((id) => id.trim()).filter((id) => id).slice(0, 500)
    const out = ec.service.sync().name('org.moqui.impl.ChatServices.get#UserStatuses').parameter('userIdList', ids)
            .disableAuthz().call()
    ec.web.sendJsonResponse({statusMap: out ? out.statusMap ?? {} : {}})
}

if (!ec.user.userId) { ec.web.sendJsonError(401, 'Authentication required') } else {
    const params = ec.web.parameters
    ec.service.sync().name('org.moqui.impl.ChatServices.signal#Typing').parameters({chatRoomId: String(params.chatRoomId),
        typing: String(params.typing) !== 'false'}).disableAuthz().call()
    ec.web.sendJsonResponse({})
}

if (!ec.user.userId) { ec.web.sendJsonError(401, 'Authentication required') } else {
    const params = ec.web.parameters
    const call = {chatRoomId: String(params.chatRoomId), eventSeq: Number(params.eventSeq)}
    for (const name of ['decision', 'feedback', 'choice', 'text']) if (params[name] != null && params[name] !== '') call[name] = String(params[name])
    const out = ec.service.sync().name('org.moqui.agent.AgentServices.decide#ChatCard').parameters(call).disableAuthz().call()
    if (ec.message.hasError()) { const errors = ec.message.errorsString; ec.message.clearErrors(); ec.web.sendJsonError(409, errors) }
    else ec.web.sendJsonResponse({status: out ? out.status ?? null : null})
}

if (!ec.user.userId) { ec.web.sendJsonError(401, 'Authentication required') } else {
    const out = ec.service.sync().name('org.moqui.impl.ChatServices.get#UnreadCounts').disableAuthz().call() || {}
    ec.web.sendJsonResponse({total: out.total ?? 0, unread: out.unread ?? 0, mentions: out.mentions ?? 0, roomCounts: out.roomCounts ?? {}})
}

if (!ec.user.userId) { ec.web.sendJsonError(401, 'Authentication required') } else {
    const out = ec.service.sync().name('org.moqui.impl.ResourceServices.upload#RichTextImage')
        .parameter('contentFile', ec.web.multiPartParameters.contentFile).disableAuthz().call()
    if (ec.message.hasError()) ec.web.sendJsonError(400, ec.message.errorsString)
    else ec.web.sendJsonResponse({ url: out && out.url ? out.url : '' })
}

if (!ec.user.userId) { ec.web.sendJsonError(401, 'Authentication required') } else {
    const out = ec.service.sync().name('org.moqui.impl.ResourceServices.get#RichTextImage')
        .parameter('imageId', String(imageId || '')).disableAuthz().call()
    if (ec.message.hasError() || !out || !out.location) ec.web.sendJsonError(404, 'No image')
    else ec.web.sendResourceResponse(out.location, true)
}
